CREATE TABLE post (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,author_id BIGINT NOT NULL,category VARCHAR(20) NOT NULL,title VARCHAR(50) NOT NULL,content TEXT NOT NULL,summary VARCHAR(120) NOT NULL,image_count INT NOT NULL DEFAULT 0,view_count BIGINT NOT NULL DEFAULT 0,like_count BIGINT NOT NULL DEFAULT 0,comment_count BIGINT NOT NULL DEFAULT 0,hot_score BIGINT NOT NULL DEFAULT 0,ip_region VARCHAR(100),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,INDEX idx_category_id(category,id),INDEX idx_created(create_time)
) CHARACTER SET utf8mb4;
CREATE TABLE post_image (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,uploader_id BIGINT NOT NULL,post_id BIGINT,file_name VARCHAR(80) NOT NULL,thumb_name VARCHAR(80) NOT NULL,width INT NOT NULL,height INT NOT NULL,sort INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,delete_state INT NOT NULL DEFAULT 0,UNIQUE KEY uk_file(file_name),INDEX idx_post(post_id,sort)
) CHARACTER SET utf8mb4;
CREATE TABLE post_like(id BIGINT PRIMARY KEY AUTO_INCREMENT,post_id BIGINT NOT NULL,user_id BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_post_user(post_id,user_id),INDEX idx_user(user_id,id));
CREATE TABLE post_favorite(id BIGINT PRIMARY KEY AUTO_INCREMENT,post_id BIGINT NOT NULL,user_id BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_post_user(post_id,user_id),INDEX idx_user(user_id,id));
